import csv, re, math
from collections import defaultdict
import numpy as np

with open('/app/dataset/data.csv') as f:
    rows = list(csv.DictReader(f))

def parse_amount(s, paren_mode='enclosed'):
    s = s.strip()
    if not s:
        return float('nan')
    is_neg = False
    if 'CR' in s or '-' in s:
        is_neg = True
    elif paren_mode == 'enclosed' and s.startswith('(') and s.endswith(')'):
        is_neg = True
    elif paren_mode == 'contains' and ('(' in s or ')' in s):
        is_neg = True

    s = re.sub(r'C1|C2', '', s)
    s = re.sub(r'[^0-9,.]', '', s)
    if not s:
        return float('nan')
    c_count = s.count(',')
    d_count = s.count('.')
    if c_count > 0 and d_count > 0:
        last_c = s.rfind(',')
        last_d = s.rfind('.')
        if last_d > last_c:
            s = s.replace(',', '')
        else:
            s = s.replace('.', '').replace(',', '.')
    elif c_count > 0:
        parts = s.split(',')
        if len(parts[-1]) == 2:
            s = ''.join(parts[:-1]) + '.' + parts[-1]
        else:
            s = s.replace(',', '')
    elif d_count > 0:
        parts = s.split('.')
        if len(parts[-1]) == 2:
            s = ''.join(parts[:-1]) + '.' + parts[-1]
        else:
            s = s.replace('.', '')
    val = float(s)
    return -val if is_neg else val

def parse_all(paren_mode):
    parsed = []
    for idx, r in enumerate(rows):
        base = parse_amount(r['amount_str'], paren_mode)
        notes = r['notes']
        m = re.search(r'items=(\d+)', notes)
        items = int(m.group(1)) if m else None
        m = re.search(r'adj=([+-]?\d+(?:\.\d+)?)%', notes)
        adj_pct = float(m.group(1))/100.0 if m else 0.0
        m = re.search(r'fee=([+-]?\d+(?:\.\d+)?)', notes)
        fee = float(m.group(1)) if m else 0.0
        waive = bool(re.search(r'waive=true', notes, re.IGNORECASE))

        if math.isnan(base):
            net = float('nan')
        elif waive:
            net = 0.0
        else:
            net = base * (1 + adj_pct) + fee

        parsed.append({
            'idx': idx,
            'record_id': r['record_id'],
            'event_time': r['event_time'].strip(),
            'region': r['region'].strip(),
            'channel': r['channel'].strip().lower(),
            'net': net,
            'items': items,
        })
    return parsed

p_enc = parse_all('enclosed')

# P3: filter Q4 first, then dedup, then filter channel != phone and finite net
q4_rows = [r for r in p_enc if r['event_time'] and '2025-10-01T00:00:00Z' <= r['event_time'] <= '2025-12-31T23:59:59Z']
by_rid3 = defaultdict(list)
for p in q4_rows:
    by_rid3[p['record_id']].append(p)
dedup3 = []
for rid, g in by_rid3.items():
    best = max(g, key=lambda x: (x['event_time'], 1 if not math.isnan(x['net']) else 0, -x['idx']))
    dedup3.append(best)
p3 = [r for r in dedup3 if r['channel'] != 'phone' and not math.isnan(r['net'])]

print('P3 count:', len(p3))
g3 = defaultdict(list)
for r in p3:
    g3[(r['region'], r['event_time'][:7])].append(r)
print('P3 groups:', {k: len(v) for k, v in sorted(g3.items())})
